Here is the root cause:
The bug arises from inadequate locking mechanisms when multiple transmit queues concurrently access and modify a shared descriptor list. This lack of global serialization allows the SYSTEMPORT hardware to operate on corrupted descriptors, leading to incorrect packet lengths and checksums for both UDP and TCP packets.

Here is the patch:

 static netdev_tx_t bcm_sysport_xmit(struct sk_buff *skb,
 				    struct net_device *dev)
 {
 	struct bcm_sysport_priv *priv = netdev_priv(dev);
 	struct device *kdev = &priv->pdev->dev;
 	struct bcm_sysport_tx_ring *ring;
+	unsigned long flags, desc_flags;
 	struct bcm_sysport_cb *cb;
 	struct netdev_queue *txq;
 	u32 len_status, addr_lo;
 	unsigned int skb_len;
-	unsigned long flags;
 	dma_addr_t mapping;
 	u16 queue;
 	int ret;

 	queue = skb_get_queue_mapping(skb);
 	txq = netdev_get_tx_queue(dev, queue);
 	ring = &priv->tx_rings[queue];

 	/* lock against tx reclaim in BH context and TX ring full interrupt */
 	spin_lock_irqsave(&ring->lock, flags);
 	if (unlikely(ring->desc_count == 0)) {
 		netif_tx_stop_queue(txq);
 		netdev_err(dev, "queue %d awake and ring full!\n", queue);
 		ret = NETDEV_TX_BUSY;
 		goto out;
 	}

 	/* Insert TSB and checksum infos */
 	if (priv->tsb_en) {
 		skb = bcm_sysport_insert_tsb(skb, dev);
 		if (!skb) {
 			ret = NETDEV_TX_OK;
 			goto out;
 		}
 	}

 	skb_len = skb->len;

 	mapping = dma_map_single(kdev, skb->data, skb_len, DMA_TO_DEVICE);
 	if (dma_mapping_error(kdev, mapping)) {
 		priv->mib.tx_dma_failed++;
 		netif_err(priv, tx_err, dev, "DMA map failed at %p (len=%d)\n",
 			  skb->data, skb_len);
 		ret = NETDEV_TX_OK;
 		goto out;
 	}

 	/* Remember the SKB for future freeing */
 	cb = &ring->cbs[ring->curr_desc];
 	cb->skb = skb;
 	dma_unmap_addr_set(cb, dma_addr, mapping);
 	dma_unmap_len_set(cb, dma_len, skb_len);

 	addr_lo = lower_32_bits(mapping);
 	len_status = upper_32_bits(mapping) & DESC_ADDR_HI_MASK;
 	len_status |= (skb_len << DESC_LEN_SHIFT);
 	len_status |= (DESC_SOP | DESC_EOP | TX_STATUS_APP_CRC) <<
 		       DESC_STATUS_SHIFT;
 	if (skb->ip_summed == CHECKSUM_PARTIAL)
 		len_status |= (DESC_L4_CSUM << DESC_STATUS_SHIFT);
 	if (skb_vlan_tag_present(skb))
 		len_status |= (TX_STATUS_VLAN_VID_TSB << DESC_STATUS_SHIFT);

 	ring->curr_desc++;
 	if (ring->curr_desc == ring->size)
 		ring->curr_desc = 0;
 	ring->desc_count--;

 	/* Ports are latched, so write upper address first */
+	spin_lock_irqsave(&priv->desc_lock, desc_flags);
 	tdma_writel(priv, len_status, TDMA_WRITE_PORT_HI(ring->index));
 	tdma_writel(priv, addr_lo, TDMA_WRITE_PORT_LO(ring->index));
+	spin_unlock_irqrestore(&priv->desc_lock, desc_flags);

 	/* Check ring space and update SW control flow */
 	if (ring->desc_count == 0)
 		netif_tx_stop_queue(txq);

 	netif_dbg(priv, tx_queued, dev, "ring=%d desc_count=%d, curr_desc=%d\n",
 		  ring->index, ring->desc_count, ring->curr_desc);

 	ret = NETDEV_TX_OK;
 out:
 	spin_unlock_irqrestore(&ring->lock, flags);
 	return ret;
 }


 static int bcm_sysport_open(struct net_device *dev)
 {
 	struct bcm_sysport_priv *priv = netdev_priv(dev);
 	struct phy_device *phydev;
 	unsigned int i;
 	int ret;

 	clk_prepare_enable(priv->clk);

 	/* Reset UniMAC */
 	umac_reset(priv);

 	/* Flush TX and RX FIFOs at TOPCTRL level */
 	topctrl_flush(priv);

 	/* Disable the UniMAC RX/TX */
 	umac_enable_set(priv, CMD_RX_EN | CMD_TX_EN, 0);

 	/* Enable RBUF 2bytes alignment and Receive Status Block */
 	rbuf_init(priv);

 	/* Set maximum frame length */
 	if (!priv->is_lite)
 		umac_writel(priv, UMAC_MAX_MTU_SIZE, UMAC_MAX_FRAME_LEN);
 	else
 		gib_set_pad_extension(priv);

 	/* Apply features again in case we changed them while interface was
 	 * down
 	 */
 	bcm_sysport_set_features(dev, dev->features);

 	/* Set MAC address */
 	umac_set_hw_addr(priv, dev->dev_addr);

 	phydev = of_phy_connect(dev, priv->phy_dn, bcm_sysport_adj_link,
 				0, priv->phy_interface);
 	if (!phydev) {
 		netdev_err(dev, "could not attach to PHY\n");
 		ret = -ENODEV;
 		goto out_clk_disable;
 	}

 	/* Reset house keeping link status */
 	priv->old_duplex = -1;
 	priv->old_link = -1;
 	priv->old_pause = -1;

 	/* mask all interrupts and request them */
 	bcm_sysport_mask_all_intrs(priv);

 	ret = request_irq(priv->irq0, bcm_sysport_rx_isr, 0, dev->name, dev);
 	if (ret) {
 		netdev_err(dev, "failed to request RX interrupt\n");
 		goto out_phy_disconnect;
 	}

 	if (!priv->is_lite) {
 		ret = request_irq(priv->irq1, bcm_sysport_tx_isr, 0,
 				  dev->name, dev);
 		if (ret) {
 			netdev_err(dev, "failed to request TX interrupt\n");
 			goto out_free_irq0;
 		}
 	}

 	/* Initialize both hardware and software ring */
+	spin_lock_init(&priv->desc_lock);
 	for (i = 0; i < dev->num_tx_queues; i++) {
 		ret = bcm_sysport_init_tx_ring(priv, i);
 		if (ret) {
 			netdev_err(dev, "failed to initialize TX ring %d\n",
 				   i);
 			goto out_free_tx_ring;
 		}
 	}

 	/* Initialize linked-list */
